const message = $input.first().json.message;
const userId = message.from.id;
const userName = message.from.first_name;
const text = message.text || '';
const chatId = message.chat.id;

if (text.startsWith('/start')) {
  return { json: { command: 'start', user_id: userId, user_name: userName, chat_id: chatId } };
}

if (text.startsWith('/help')) {
  return { json: { command: 'help', user_id: userId, user_name: userName, chat_id: chatId } };
}

const category = text.replace('/search', '').trim();
return {
  json: {
    command: 'search',
    user_id: userId,
    user_name: userName,
    chat_id: chatId,
    category: category || 'wireless headphones',
    timestamp: new Date().toISOString()
  }
};

const items = $input.all();
const category = items[0].json.product_category;
const chatId = items[0].json.chat_id;

let message = `📊 *Найдено ${items.length} поставщиков: ${category}*\n\n`;

items.forEach((item, index) => {
  const d = item.json;
  const num = index + 1;
  const star = d.recommended === 'YES' ? '⭐️' : '📍';

  message += `${star} *${num}. ${d.company_name}*\n`;
  message += `🎯 Оценка: ${d.ai_score}/10 | ⭐️ Рейтинг: ${d.rating}/5\n`;
  message += `📦 MOQ: ${d.moq} | 💰 Цена: ${d.price}\n`;
  message += `📍 ${d.location}\n`;
  message += `📧 ${d.contact_email}\n`;
  message += `🌐 ${d.company_url}\n`;
  message += `✅ ${d.pros}\n`;
  message += `⚠️ ${d.risks}\n\n`;
});

message += `_Данные готовы к сохранению в Google Sheets_ 📝`;

return {
  json: {
    chat_id: chatId,
    message: message
  }
};
